class CSData{static $inject=["$http"];constructor($http){this.$http=$http}async allocateJobs(courierId,dispId,jobIds){return await this.$http.post("job/Allocate?courierId="+courierId+"&dispId="+dispId+"&jobIds="+jobIds)}async addRestoreEvent(jobNo,clientId,contact,staffId,courierId,jobId,jobType,despatcherName){let response=await this.$http.post("job/AddRestoreEvent?jobNo="+jobNo+"&clientId="+clientId+"&contact="+contact+"&staffId="+staffId+"&courierId="+courierId+"&jobId="+jobId+"&jobType="+jobType+"&despatcherName="+despatcherName);return response.data}async getPodJobs({courierId,clientId,wild,job,fromDate,toDate,pageIndex,pageSize}){let response=await this.$http.get("/Job/PODSearch?courierId="+courierId+"&clientId="+clientId+"&wild="+wild+"&job="+job+"&fromDate="+fromDate.toISOString()+"&toDate="+toDate.toISOString()+"&pageIndex="+pageIndex+"&pageSize="+pageSize);return response.data}async searchBulkJobs(courierId,clientId,job,wild,fromDate,toDate,pageIndex,pageSize){let response=await this.$http.get("/Job/BulkSearch?courierId="+courierId+"&clientId="+clientId+"&job="+job+"&wild="+wild+"&fromDate="+fromDate.toISOString()+"&toDate="+toDate.toISOString()+"&pageIndex="+pageIndex+"&pageSize="+pageSize);return response.data}async searchPreBookJobs(courierId,clientId,wild,job,fromDate,toDate,pageIndex,pageSize){let response=await this.$http.get("/Job/PreBookSearch?courierId="+courierId+"&clientId="+clientId+"&wild="+wild+"&job="+job+"&fromDate="+fromDate.toISOString()+"&toDate="+toDate.toISOString()+"&pageIndex="+pageIndex+"&pageSize="+pageSize);return response.data}async getCourierRoute(code,start,end){let response=await this.$http.get("/courier/route?code="+code+"&start="+start.format("YYYY-MM-DDTHH:mm:ss")+"&end="+end.format("YYYY-MM-DDTHH:mm:ss"));return response.data}async getJobDetail(jobId){let response=await this.$http.get("/Job/Detail?jobId="+jobId);return response.data}async getRelatedJobs(parentId,clientId){let response=await this.$http.get("/Job/Related?parentId="+parentId+"&clientId="+clientId);return response.data}async getScanDetail(runDate,scan){let response=await this.$http.get("/Job/ScanJobDetail?runDate="+runDate.toISOString()+"&scan="+scan);return response.data}async getPreBookDetail(preBookJobId){let response=await this.$http.get("/Job/PreBookDetail?preBookJobId="+preBookJobId);return response.data}async getBulkJobDetail(bulkJobId){let response=await this.$http.get("/Job/BulkDetail?bulkJobId="+bulkJobId);return response.data}async getBulkJobPhoto(bulkJobId){let response=await this.$http.get("/CS/GetBulkJobPhoto?bulkJobId="+bulkJobId);return response.data}async getActiveCouriers(){let response=await this.$http.get("courier/active");return response.data}async getAllCouriers(){let response=await this.$http.get("courier/AllActive");return response.data}async addEventNote(eventId,note){let response=await this.$http.post("CS/AddEventNote?eventId="+eventId+"&note="+note+"&userName="+ClientName);return response.data}async validateSwapPOD(jobNumber){let response=await this.$http.post("Job/ValidateSwapPOD?job="+jobNumber);return response.data}async restoreJobs(courierId,dispId,jobIds){let response=await this.$http.post("job/RestoreJobs?courierId="+courierId+"&dispId="+dispId+"&jobIds="+jobIds);return response.data}async restoreSplitJobs(courierId,dispId,jobIds){let response=await this.$http.post("job/RestoreSplitJobs?courierId="+courierId+"&dispId="+dispId+"&jobIds="+jobIds);return response.data}async swapPOD(job1,job2){let response=await this.$http.post("Job/SwapPOD?job1="+job1+"&job2="+job2);return response.data}async closeEvent(eventId,userName){let response=await this.$http.post("CS/CloseEvent?eventId="+eventId+"&userName="+`${ClientName}-${userName}`);return response.data}async reSendJobs(jobIds){let response=await this.$http.post("job/ReSendSelected?jobIds="+jobIds);return response.data}async reAssignJobs(jobIds){let response=await this.$http.post("job/ReAssignSelected?jobIds="+jobIds);return response.data}async sendPOD(jobId,email){let response=await this.$http.get("job/SendPOD?jobId="+jobId+"&toEmail="+email);return response.data}async unSplitJob(jobId){let response=await this.$http.post("job/UnSplitJob?jobId="+jobId);return response.data}async generateDirectLink(eventId,clientId){let response=await this.$http.get("/CS/GenerateDirectLink?eventId="+eventId+"&clientId="+clientId);return response.data}async createEvent(data,notify){try{let response1=await this.$http({url:"book/CreateEvent?clientInternal="+ClientInternal+"&notify="+notify+"&clientName="+ClientName,method:"POST",data:data});return response1.data}catch(response2){console.error("Book/CreateEvent error",response2.status,response2.data)}}async getActiveClients(searchTerm){let response=await this.$http.get("/home/ActiveClients?searchTerm="+searchTerm);return response.data}async getActiveCouriersSearch(searchTerm){let response=await this.$http.get("/courier/AllActiveSearch?searchTerm="+searchTerm);return response.data}async doAPI(path,data){let response=await this.$http.post(path,data);return response.data}}angular.module("uDispatch").factory("uCSData",CSData);